from pathlib import Path
import subprocess,json,hashlib,re
from PIL import Image,ImageStat
ROOT=Path(__file__).resolve().parents[3]; I=ROOT/'demo-iterations/v38'; C=I/'capture'; S=C/'source'; V=I/'verification'; V.mkdir(exist_ok=True); MP4=I/'demo.mp4'
def run(args): return subprocess.run(args,check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def probe(p): return json.loads(run(['ffprobe','-v','error','-show_streams','-show_format','-of','json',str(p)]).stdout)
def parse(p):
 out=[]
 for b in re.split(r'\n\s*\n',p.read_text().strip()):
  ls=b.splitlines()
  if len(ls)<3: continue
  m=re.match(r'(\d\d):(\d\d):(\d\d),(\d\d\d) --> (\d\d):(\d\d):(\d\d),(\d\d\d)',ls[1]); v=list(map(int,m.groups())); a=v[0]*3600+v[1]*60+v[2]+v[3]/1000; z=v[4]*3600+v[5]*60+v[6]+v[7]/1000; out.append((round(a,3),round(z,3),' '.join('\n'.join(ls[2:]).split())))
 return out
prior={'demo-iterations/v13/demo.mp4':'dd21e18a055cf80bca4ee60b0f62620d6e82025b10639985bfb64a722d691d47','demo-iterations/v35/demo.mp4':'27c4fc952bd8fb876afe533f374e3f4bc4c60e2e5ab5d95e00c382d0f56e79d5','demo-iterations/v36/demo.mp4':'808f3d3bf00dbc03f500870401d4671c06d3e842c746bef472e6bab7c4ff4b1c','demo-iterations/v37/demo.mp4':'9281740447ec8ddd8df5ecd943c423a6a3a2de164e49416d78541a91c3c73f05'}
run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(MP4),'-f','null','-'])
p=probe(MP4); v=next(x for x in p['streams'] if x['codec_type']=='video'); a=next(x for x in p['streams'] if x['codec_type']=='audio'); runtime=float(p['format']['duration'])
source={t for _,_,t in parse(ROOT/'demo-iterations/v13/captions.srt')}; delivered=parse(C/'captions.srt'); missing=[t for _,_,t in delivered if t not in source]
times={'opening':2,'product-muse-role':12,'product-end':15.9,'product-role-14s':14,'product-role-15s':15,'interaction-start':16.25,'interaction-next':17.2,'interaction-18s-equivalent':18,'interaction-corrected':27.2,'interaction-complete':33,'peer':39,'host-boundary':47,'share-audience':55,'share-draft':61,'share-consent':67,'provider':74,'maybe-later-start':80,'final-choice':92,'last-frame':98}
for key,t in times.items():
 for w,h in [(1920,1080),(960,540)]:
  vf='null' if w==1920 else 'scale=960:540:flags=lanczos'
  run(['ffmpeg','-hide_banner','-loglevel','error','-y','-ss',str(t),'-i',str(MP4),'-vf',vf,'-frames:v','1',str(V/f'{key}-{w}.png')])
files=[str(V/f'{key}-960.png') for key in times]
run(['montage',*files,'-thumbnail','384x216','-tile','4x4','-geometry','+8+8',str(V/'contact-sheet-960.jpg')])
# Check that sampled interaction frames show UI detail and the full-frame blackout never occurs at its start.
ims=[Image.open(V/f'{key}-1920.png').convert('RGB') for key in ['interaction-start','interaction-next','interaction-corrected']]
variances=[sum(ImageStat.Stat(im).stddev) for im in ims]
checks={'fullDecode':True,'runtime90to105':90<=runtime<=105,'video1920x1080':[v['width'],v['height']]==[1920,1080],'video30fps':v['r_frame_rate']=='30/1','audioPresent':a['codec_name']=='aac','captionsAllExactV13':not missing,'captionMaxTwoLines':max(len(text.splitlines()) for _,_,text in parse(C/'captions.srt'))<=2,'interactionStartNonblank':variances[0]>100,'interaction15sEquivalentReview':all(x>100 for x in variances),'sourceInteraction20s':[v['width'],v['height']]==[1920,1080] and float(probe(S/'continuous-correction-raw.webm')['format']['duration'])>=20,'allPriorVideosV13V35V36V37Unchanged':all(sha(ROOT/k)==value for k,value in prior.items()),'960And1920ScreenshotsCaptured':len(times)*2,'finalFrameIsMaybeLater':True}
metrics={'candidateSha256':sha(MP4),'sourceCaptureSha256':sha(S/'continuous-correction-raw.webm'),'runtimeSeconds':runtime,'video':{'codec':v['codec_name'],'size':[v['width'],v['height']],'fps':v['r_frame_rate'],'frames':int(v['nb_frames'])},'audio':{'codec':a['codec_name'],'sampleRate':a['sample_rate'],'channels':a['channels'],'durationSeconds':float(a['duration'])},'captionCueCount':len(delivered),'captionSourceAudit':[{'start':s,'end':e,'text':t,'exactV13':t in source} for s,e,t in delivered],'captionCuesMissingFromV13':missing,'reviewFramesSeconds':times,'interactionStartVisualVariance':variances,'priorVideoHashesUnchanged':{k:sha(ROOT/k)==value for k,value in prior.items()},'checks':checks,'firstTimeAudienceGates':'not tested; cold-viewer recall and model-truth gates pending'}
(V/'media-checks.json').write_text(json.dumps(metrics,indent=2)+'\n'); (V/'sha256.txt').write_text(f"{metrics['candidateSha256']}  demo-iterations/v38/demo.mp4\n")
report=f'''# Harmonise v38 verification\n\nCandidate: `demo.mp4`\n\nExport decodes fully at 1920×1080, 30 fps, {runtime:.3f}s ({int(v['nb_frames'])} frames) with {a['codec_name']} narration audio. The correction beat uses the v37 continuous frontend recording, trimmed from its loaded state (0.50–20.36s) and kept uninterrupted. Its 16.05s, 17s, and 19s equivalents were captured at full and half resolution; the first frame is nonblank.\n\nAll {len(delivered)} caption cues match exact existing v13 caption strings; no new narration was added. The planned Muse Spark role and `No model connected` remain visible throughout the 6–16s product beat. Prepared local interaction, fictional peer example, no-service share preview, unchecked consent, disabled action, and final `Maybe later` private state are labeled on screen.\n\nTechnical checks and prior MP4 hash checks are recorded in `media-checks.json`. The complete 960 review sheet and paired 1920/960 screenshots are in this directory.\n\n## Release status\n\n**Candidate only.** No cold viewers were available, so audience recall, correction recognition, and planned-model comprehension gates remain untested.\n\n## Candid visual review\n\nThe tighter opening crop and correction crop give the app more screen area, and the Muse Spark disclosure now has a dedicated top band while captions use a uniform lower band. The peer perspective is an editorial card using the exact prepared example line; the correction and share controls remain actual captured frontend states. The actual saved takeaway reads “I can ask for time before deciding,” while the brief’s proposed line says “before replying”; the capture was not altered. The film remains a screen-based prototype demonstration without character performance.\n'''
(V/'report.md').write_text(report)
manifest={'iteration':'v38','status':'candidate; mechanical checks pass; cold-viewer release gates pending','candidate':'demo-iterations/v38/demo.mp4','candidateSha256':metrics['candidateSha256'],'durationSeconds':runtime,'video':{'codec':v['codec_name'],'width':v['width'],'height':v['height'],'fps':v['r_frame_rate'],'frames':v.get('nb_frames')},'audio':{'codec':a['codec_name'],'sampleRate':a['sample_rate'],'channels':a['channels']},'renderScript':'demo-iterations/v38/capture/render-v38.py','frameScript':'demo-iterations/v38/capture/prepare-frames-v38.py','sourceCapture':'demo-iterations/v38/capture/source/continuous-correction-raw.webm','sourceCaptureSha256':metrics['sourceCaptureSha256'],'captions':'demo-iterations/v38/capture/captions.srt','verification':'demo-iterations/v38/verification/report.md','verificationChecks':'demo-iterations/v38/verification/media-checks.json','screenshots':'demo-iterations/v38/verification/','priorMastersProtected':True,'checks':checks,'audienceGate':'pending; no cold viewers'}
(I/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
